arguments.command:
cat > index.html <<'EOF'
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Chasen — AI 开发工程师 / AI 原住民</title>
<meta name="description" content="Chasen（Chasen Liao），20 岁，计算机科学大四，广州。AI 开发工程师，做 Pi 桌面客户端和 Agent Skills，开放 AI 开发与 AI 产品机会。">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500&family=Noto+Serif+SC:wght@400;500&display=swap" rel="stylesheet">
<style>
  :root{
    --coral:#cc785c;
    --coral-active:#a9583e;
    --ink:#141413;
    --body:#3d3d3a;
    --body-strong:#252523;
    --muted:#6c6a64;
    --muted-soft:#8e8b82;
    --hairline:#e6dfd8;
    --hairline-soft:#ebe6df;
    --canvas:#faf9f5;
    --soft:#f5f0e8;
    --card:#efe9de;
    --cream-strong:#e8e0d2;
    --dark:#181715;
    --dark-elev:#252320;
    --dark-soft:#1f1e1b;
    --on-dark:#faf9f5;
    --on-dark-soft:#a09d96;
    --serif:"Cormorant Garamond","Noto Serif SC","Songti SC",Garamond,serif;
    --sans:"Inter","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;
    --mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
    --wrap:1120px;
    --radius:12px;
  }
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  @media (prefers-reduced-motion: reduce){html{scroll-behavior:auto}}
  body{
    margin:0;
    background:var(--canvas);
    color:var(--body);
    font-family:var(--sans);
    font-size:16px;
    line-height:1.55;
    -webkit-font-smoothing:antialiased;
    text-rendering:optimizeLegibility;
  }
  a{color:inherit;text-decoration:none}
  img{display:block;max-width:100%}
  ul{margin:0;padding:0;list-style:none}
  ::selection{background:var(--coral);color:#fff}
  :focus-visible{outline:2px solid var(--coral);outline-offset:3px;border-radius:4px}

  .wrap{max-width:var(--wrap);margin:0 auto;padding:0 24px}
  .serif{font-family:var(--serif);font-weight:500;letter-spacing:-.02em}
  .mono{font-family:var(--mono)}

  .spike{width:15px;height:15px;flex:none;display:inline-block;vertical-align:-2px}

  /* ---------- nav ---------- */
  .nav{
    border-bottom:1px solid var(--hairline);
    background:var(--canvas);
    position:sticky;top:0;z-index:50;
  }
  .nav-inner{height:64px;display:flex;align-items:center;justify-content:space-between;gap:24px}
  .brand{display:inline-flex;align-items:center;gap:10px;font-family:var(--serif);font-size:24px;font-weight:500;letter-spacing:-.02em;color:var(--ink)}
  .brand .spike{color:var(--coral);width:16px;height:16px}
  .nav-menu{display:flex;align-items:center;gap:28px;margin-left:auto;margin-right:32px}
  .nav-menu a{font-size:14px;font-weight:500;color:var(--body)}
  .nav-menu a:hover{color:var(--ink)}
  .nav-cta{
    display:inline-flex;align-items:center;gap:8px;
    background:var(--coral);color:#fff;
    font-size:14px;font-weight:500;line-height:1;
    padding:12px 20px;height:40px;border-radius:8px;
    transition:background .15s ease;
  }
  .nav-cta:hover{background:var(--coral-active)}
  .nav-cta .tiny{font-family:var(--mono);font-size:9px;letter-spacing:.08em;opacity:.75;border-left:1px solid rgba(255,255,255,.4);padding-left:8px}
  .nav-toggle{display:none;background:none;border:0;padding:8px;cursor:pointer;color:var(--ink)}
  .nav-toggle svg{width:24px;height:24px;display:block}
  .mobile-menu{display:none;border-top:1px solid var(--hairline);background:var(--canvas)}
  .mobile-menu.open{display:block}
  .mobile-menu ul{padding:8px 0 16px}
  .mobile-menu a{display:block;padding:12px 24px;font-size:15px;font-weight:500;color:var(--ink)}
  .mobile-menu .tip{padding:0 24px 16px;font-family:var(--mono);font-size:10px;letter-spacing:.08em;color:var(--muted-soft)}

  /* ---------- hero ---------- */
  .hero{padding:88px 0 96px}
  .hero-grid{display:grid;grid-template-columns:1.04fr .96fr;gap:64px;align-items:center}
  .eyebrow{
    display:inline-flex;align-items:center;gap:8px;
    font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;
    color:var(--muted);margin-bottom:22px;
  }
  .eyebrow .spike{width:11px;height:11px;color:var(--coral)}
  h1{
    font-family:var(--serif);font-weight:500;
    font-size:clamp(58px,8.4vw,92px);
    line-height:.98;letter-spacing:-.035em;
    color:var(--ink);margin:0 0 10px;
  }
  h1 .dot{color:var(--coral)}
  .name-note{
    font-family:var(--serif);font-size:19px;font-style:italic;
    color:var(--muted);margin:0 0 26px;letter-spacing:-.01em;
  }
  .lead{
    font-size:19px;line-height:1.55;color:var(--body-strong);
    max-width:31em;margin:0 0 16px;
  }
  .lead em{font-style:normal;font-weight:500;color:var(--ink);border-bottom:1px solid var(--hairline);padding-bottom:1px}
  .hero-body{font-size:15px;line-height:1.7;color:var(--muted);max-width:33em;margin:0 0 30px}
  .cta-row{display:flex;flex-wrap:wrap;gap:12px;align-items:center}
  .btn{
    display:inline-flex;align-items:center;gap:8px;
    height:44px;padding:0 22px;border-radius:8px;
    font-size:14px;font-weight:500;line-height:1;
    transition:background .15s ease, border-color .15s ease;
  }
  .btn-primary{background:var(--coral);color:#fff}
  .btn-primary:hover{background:var(--coral-active)}
  .btn-secondary{background:var(--canvas);color:var(--ink);border:1px solid var(--hairline)}
  .btn-secondary:hover{border-color:var(--muted-soft)}
  .cta-note{
    font-family:var(--mono);font-size:10px;letter-spacing:.06em;
    color:var(--muted-soft);margin:14px 0 0;
  }
  .hero-meta{
    display:flex;flex-wrap:wrap;gap:8px 18px;align-items:center;
    margin:28px 0 0;padding-top:20px;border-top:1px solid var(--hairline);
    font-family:var(--mono);font-size:11px;letter-spacing:.06em;color:var(--muted);
  }
  .hero-meta li{display:flex;align-items:center;gap:8px}
  .hero-meta li+li::before{content:"";width:3px;height:3px;border-radius:50%;background:var(--muted-soft);margin-right:2px}

  /* hero mockup */
  .mockup{
    background:var(--dark);border-radius:16px;overflow:hidden;
    color:var(--on-dark);border:1px solid #2a2824;
  }
  .mockup-bar{
    display:flex;align-items:center;gap:10px;
    height:44px;padding:0 16px;background:var(--dark-elev);
    border-bottom:1px solid #2e2b27;
  }
  .dots{display:flex;gap:6px}
  .dots span{width:9px;height:9px;border-radius:50%;background:#45413b}
  .mockup-bar .title{font-family:var(--mono);font-size:11px;color:var(--on-dark-soft);letter-spacing:.04em}
  .mockup-bar .ver{margin-left:auto;font-family:var(--mono);font-size:10px;color:#6f6a62}
  .mockup-body{padding:22px}
  .mockup-person{display:flex;align-items:center;gap:12px;padding-bottom:18px;border-bottom:1px solid #2b2824}
  .mockup-person img{width:44px;height:44px;border-radius:50%;object-fit:cover;filter:saturate(.92)}
  .mockup-person .who strong{display:block;font-size:14px;font-weight:500;color:var(--on-dark);line-height:1.3}
  .mockup-person .who span{display:block;font-family:var(--mono);font-size:10px;color:var(--on-dark-soft);letter-spacing:.03em}
  .status{
    margin-left:auto;display:inline-flex;align-items:center;gap:6px;
    font-family:var(--mono);font-size:9px;letter-spacing:.1em;text-transform:uppercase;
    color:#8fc9a5;background:rgba(93,184,114,.12);
    border:1px solid rgba(93,184,114,.3);border-radius:999px;padding:4px 9px;
  }
  .status i{width:5px;height:5px;border-radius:50%;background:#5db872;display:block}
  .prompt{
    font-family:var(--mono);font-size:12px;line-height:1.6;
    background:var(--dark-soft);border:1px solid #2c2925;border-radius:8px;
    padding:12px 14px;margin:18px 0 16px;color:#d8d2c7;
  }
  .prompt b{color:var(--coral);font-weight:500}
  .prompt span{color:#7f7a71}
  .rows li{
    display:flex;align-items:center;justify-content:space-between;gap:16px;
    padding:9px 0;border-bottom:1px solid #262420;
    font-size:13px;color:#d3cec4;
  }
  .rows li:last-child{border-bottom:0}
  .rows li span:last-child{font-family:var(--mono);font-size:10px;color:#77726a;letter-spacing:.03em}
  .mockup-foot{
    display:flex;align-items:center;justify-content:space-between;gap:12px;
    padding:12px 22px;border-top:1px solid #2b2824;background:#1b1a17;
    font-family:var(--mono);font-size:10px;color:var(--on-dark-soft);letter-spacing:.04em;
  }
  .mockup-foot b{color:var(--on-dark);font-weight:500}
  .mockup-caption{
    display:inline-flex;align-items:center;gap:6px;
    margin-top:12px;font-family:var(--mono);font-size:11px;
    color:var(--muted);letter-spacing:.03em;
  }
  .mockup-caption:hover{color:var(--coral)}

  /* ---------- strip ---------- */
  .strip{background:var(--soft);border-top:1px solid var(--hairline);border-bottom:1px solid var(--hairline)}
  .strip-inner{
    display:flex;flex-wrap:wrap;align-items:center;gap:10px 14px;
    padding-top:16px;padding-bottom:16px;
    font-family:var(--mono);font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);
  }
  .strip-inner .spike{width:8px;height:8px;color:var(--coral);opacity:.8}

  /* ---------- section scaffolding ---------- */
  section{padding:96px 0}
  .section-head{margin-bottom:44px;max-width:720px}
  .section-head .eyebrow{margin-bottom:14px}
  .h2{
    font-family:var(--serif);font-weight:500;
    font-size:clamp(34px,4.4vw,48px);line-height:1.1;letter-spacing:-.025em;
    color:var(--ink);margin:0 0 14px;
  }
  .section-sub{font-size:15px;line-height:1.7;color:var(--muted);margin:0;max-width:38em}

  /* ---------- about ---------- */
  #about{border-bottom:1px solid var(--hairline-soft);padding-top:0}
  .about-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:64px;align-items:start}
  .about-copy p{margin:0 0 18px;font-size:16px;line-height:1.8;color:var(--body);max-width:36em}
  .about-copy p strong{color:var(--ink);font-weight:500}
  .about-copy .first{
    font-family:var(--serif);font-size:25px;line-height:1.45;letter-spacing:-.01em;
    color:var(--ink);margin-bottom:22px;max-width:26em;
  }
  .about-sign{
    display:flex;align-items:center;gap:10px;margin-top:28px;
    font-family:var(--mono);font-size:10px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted-soft);
  }
  .about-sign .spike{width:11px;height:11px;color:var(--coral)}
  .chibi-card{
    background:var(--card);border-radius:var(--radius);padding:14px;
    transform:rotate(1.2deg);
  }
  .chibi-card img{border-radius:8px;width:100%;height:auto;aspect-ratio:3/4;object-fit:cover;object-position:center 35%}
  .chibi-card figcaption{
    padding:14px 6px 4px;font-family:var(--mono);font-size:10px;line-height:1.6;
    letter-spacing:.03em;color:var(--muted);
  }
  .chibi-card figcaption b{display:block;color:var(--ink);font-weight:500;margin-bottom:3px;letter-spacing:.06em}

  /* ---------- work ---------- */
  #work{padding-top:96px}
  .work-head{display:flex;align-items:flex-end;justify-content:space-between;gap:32px;margin-bottom:44px}
  .work-head .section-head{margin-bottom:0}
  .work-count{font-family:var(--mono);font-size:10px;letter-spacing:.1em;color:var(--muted-soft);text-align:right;line-height:1.7;flex:none}
  .work-count b{display:block;font-family:var(--serif);font-size:40px;font-weight:500;color:var(--ink);letter-spacing:-.02em;line-height:1}

  .flagship{
    background:var(--dark);color:var(--on-dark);border-radius:var(--radius);
    padding:40px;display:grid;grid-template-columns:1.08fr .92fr;gap:44px;
    border:1px solid #2a2824;margin-bottom:20px;
  }
  .flagship .tag{
    display:inline-flex;align-items:center;gap:8px;
    font-family:var(--mono);font-size:10px;letter-spacing:.13em;text-transform:uppercase;
    color:var(--coral);margin-bottom:18px;
  }
  .flagship .tag .spike{width:9px;height:9px}
  .flagship h3{
    font-family:var(--serif);font-size:clamp(32px,3.6vw,44px);font-weight:500;
    line-height:1.05;letter-spacing:-.025em;margin:0 0 8px;color:var(--on-dark);
  }
  .flagship .repo-path{font-family:var(--mono);font-size:10px;color:#77726a;letter-spacing:.04em;margin-bottom:18px}
  .flagship p{font-size:14px;line-height:1.75;color:#c9c4ba;margin:0 0 20px;max-width:34em}
  .chips{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:24px}
  .chips li{
    font-family:var(--mono);font-size:10px;letter-spacing:.03em;
    color:#bdb8ae;background:#24221f;border:1px solid #302d28;
    border-radius:999px;padding:5px 10px;
  }
  .chips li.star{color:var(--on-dark);border-color:#3d3933}
  .flagship .link{
    display:inline-flex;align-items:center;gap:7px;
    font-size:13px;font-weight:500;color:var(--on-dark);
    border-bottom:1px solid #4a453e;padding-bottom:3px;
  }
  .flagship .link:hover{color:var(--coral);border-color:var(--coral)}
  .code{
    background:var(--dark-soft);border:1px solid #2c2925;border-radius:8px;
    padding:18px;font-family:var(--mono);font-size:12px;line-height:1.85;
    color:#b9b4aa;overflow-x:auto;
  }
  .code .ln{color:#5f5a53;user-select:none;display:inline-block;width:2.2em}
  .code .k{color:#e0a184}
  .code .s{color:#a8c3a0}
  .code .c{color:#6c675f}
  .code-head{
    display:flex;align-items:center;justify-content:space-between;
    font-family:var(--mono);font-size:9px;letter-spacing:.12em;text-transform:uppercase;
    color:#77726a;margin-bottom:10px;
  }
  .code-head span:last-child{color:#8fc9a5}

  .work-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
  .project{
    background:var(--card);border-radius:var(--radius);padding:30px;
    display:flex;flex-direction:column;min-height:250px;
  }
  .project .num{
    display:flex;align-items:center;justify-content:space-between;gap:12px;
    font-family:var(--mono);font-size:10px;letter-spacing:.12em;color:var(--muted);
    margin-bottom:22px;
  }
  .project .num .star{color:var(--muted)}
  .project h3{
    font-family:var(--serif);font-size:26px;font-weight:500;line-height:1.15;
    letter-spacing:-.02em;margin:0 0 10px;color:var(--ink);word-break:break-word;
  }
  .project p{font-size:14px;line-height:1.7;color:var(--body);margin:0 0 22px}
  .project .foot{
    margin-top:auto;display:flex;align-items:center;justify-content:space-between;gap:14px;
    padding-top:16px;border-top:1px solid rgba(20,20,19,.09);
  }
  .project .tags{display:flex;flex-wrap:wrap;gap:6px}
  .project .tags span{font-family:var(--mono);font-size:9px;letter-spacing:.05em;color:var(--muted);border:1px solid rgba(20,20,19,.14);border-radius:999px;padding:3px 8px}
  .project .go{font-size:12px;font-weight:500;color:var(--ink);display:inline-flex;align-items:center;gap:5px;white-space:nowrap}
  .project .go:hover{color:var(--coral)}

  /* ---------- skills ---------- */
  #skills{background:var(--soft);border-top:1px solid var(--hairline);border-bottom:1px solid var(--hairline)}
  .skills-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:0;border-top:1px solid var(--hairline)}
  .skill-col{padding:30px 32px 8px 0}
  .skill-col+.skill-col{padding-left:32px;border-left:1px solid var(--hairline)}
  .skill-col h3{
    font-family:var(--mono);font-size:10px;font-weight:500;letter-spacing:.14em;
    text-transform:uppercase;color:var(--muted);margin:0 0 18px;
  }
  .skill-col li{
    display:flex;align-items:center;gap:10px;
    font-size:19px;color:var(--ink);letter-spacing:-.01em;
    padding:9px 0;border-bottom:1px solid var(--hairline-soft);
  }
  .skill-col li:last-child{border-bottom:0}
  .skill-col li .spike{width:10px;height:10px;color:var(--coral)}
  .skill-col li small{margin-left:auto;font-family:var(--mono);font-size:9px;color:var(--muted-soft);letter-spacing:.04em}
  .skill-note{font-size:13px;color:var(--muted);line-height:1.7;margin:18px 0 0;padding-bottom:24px}

  .now{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:64px}
  .now-item{border-top:1px solid var(--muted-soft);padding-top:18px}
  .now-item .idx{font-family:var(--mono);font-size:10px;letter-spacing:.1em;color:var(--coral);display:block;margin-bottom:10px}
  .now-item h4{font-family:var(--sans);font-size:15px;font-weight:500;color:var(--ink);margin:0 0 8px;line-height:1.45}
  .now-item p{font-size:13px;line-height:1.7;color:var(--muted);margin:0}

  /* ---------- contact ---------- */
  #contact{padding-bottom:96px}
  .contact-band{
    background:var(--coral);color:#fff;border-radius:var(--radius);
    padding:56px;display:grid;grid-template-columns:1.02fr .98fr;gap:56px;align-items:start;
  }
  .contact-band .eyebrow{color:rgba(255,255,255,.72);margin-bottom:16px}
  .contact-band .eyebrow .spike{color:#fff}
  .contact-band h2{
    font-family:var(--serif);font-weight:500;font-size:clamp(32px,4vw,44px);
    line-height:1.12;letter-spacing:-.025em;margin:0 0 16px;color:#fff;
  }
  .contact-band p{font-size:14px;line-height:1.75;color:rgba(255,255,255,.88);margin:0 0 24px;max-width:32em}
  .role-tags{display:flex;flex-wrap:wrap;gap:8px}
  .role-tags span{
    border:1px solid rgba(255,255,255,.42);border-radius:999px;
    padding:6px 12px;font-size:11px;font-weight:500;letter-spacing:.02em;color:#fff;
  }
  .links{display:grid;grid-template-columns:1fr 1fr;gap:8px}
  .link-tile{
    display:flex;align-items:center;justify-content:space-between;gap:10px;
    background:var(--canvas);color:var(--ink);border-radius:8px;
    padding:13px 14px;font-size:13px;font-weight:500;
    transition:background .15s ease;
  }
  .link-tile:hover{background:var(--cream-strong)}
  .link-tile .todo{
    font-family:var(--mono);font-size:9px;font-weight:400;letter-spacing:.04em;
    color:var(--muted-soft);white-space:nowrap;
  }
  .link-tile.email{grid-column:span 1}
  .links-note{
    grid-column:1 / -1;font-family:var(--mono);font-size:9px;
    letter-spacing:.05em;color:rgba(255,255,255,.7);margin:4px 0 0;line-height:1.6;
  }

  /* ---------- footer ---------- */
  footer{background:var(--dark);color:var(--on-dark-soft);padding:56px 0 40px}
  .foot-top{display:flex;justify-content:space-between;gap:40px;flex-wrap:wrap;padding-bottom:36px;border-bottom:1px solid #2c2925}
  .foot-brand{display:flex;align-items:center;gap:10px;color:var(--on-dark);font-family:var(--serif);font-size:24px;letter-spacing:-.02em;margin-bottom:12px}
  .foot-brand .spike{color:var(--coral)}
  .foot-note{font-size:12px;line-height:1.7;color:var(--on-dark-soft);max-width:26em;margin:0}
  .foot-nav{display:flex;flex-wrap:wrap;gap:12px 28px;align-items:flex-start}
  .foot-nav a{font-size:13px;color:var(--on-dark-soft)}
  .foot-nav a:hover{color:var(--on-dark)}
  .foot-bottom{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap;padding-top:22px;font-family:var(--mono);font-size:10px;letter-spacing:.04em;color:#77726a}
  .foot-bottom a{color:#a09d96;border-bottom:1px solid #3d3933;padding-bottom:1px}
  .foot-bottom a:hover{color:var(--on-dark)}

  /* ---------- responsive ---------- */
  @media (max-width:1000px){
    .hero-grid{grid-template-columns:1fr;gap:44px}
    .hero{padding:64px 0 72px}
    .hero-art{max-width:560px}
    .about-grid{grid-template-columns:1fr;gap:40px}
    .chibi-card{max-width:340px;transform:none}
